-- Datos de DESARROLLO: propiedades y leads de ejemplo para la corredora "UrbeGestión (dev)".
-- No es una migración. Es seguro repetirlo solo si antes se vacían las tablas (no usa on conflict).

insert into public.properties (tenant_id, title, operation, property_type, price_uf, commune, address, bedrooms, bathrooms, built_area_m2, total_area_m2, parking_spots, storage_units, featured, status, images, video_url, description, features, virtual_tour_url, expenses_monthly_clp, map_query, lat, lng, created_at) values ((select id from public.tenants where name = 'UrbeGestión (dev)'), 'Penthouse Dúplex de Lujo con Terraza Panorámica', 'venta', 'departamento', 18500, 'Vitacura', 'Av. Nueva Costanera / Alonso de Córdova', 4, 4, 240, 310, 3, 2, true, 'disponible', array['https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&q=80&w=1200']::text[], null, 'Exclusivo penthouse dúplex en el corazón de Vitacura. Finas terminaciones, piso de madera natural, cocina equipada con isla de mármol, terraza privada con jacuzzi y vista despejada a la cordillera. Seguridad 24/7 y acceso directo con ascensor privado.', array['Terraza Panorámica Privada', 'Jacuzzi Exterior', 'Ascensor Directo al Depto', 'Dormitorio Principal en Suite con Walk-in Closet', 'Termopanel en Todas las Ventanas', 'Calefacción por Losa Radiante', '3 Estacionamientos Subterráneos']::text[], 'https://my.matterport.com/show/?m=demo_luxury_1', 380000, 'Alonso de Cordova, Vitacura, Región Metropolitana, Chile', null, null, '2026-08-15');
insert into public.properties (tenant_id, title, operation, property_type, price_uf, commune, address, bedrooms, bathrooms, built_area_m2, total_area_m2, parking_spots, storage_units, featured, status, images, video_url, description, features, virtual_tour_url, expenses_monthly_clp, map_query, lat, lng, created_at) values ((select id from public.tenants where name = 'UrbeGestión (dev)'), 'Casa Mediterránea en Condominio Cerrado La Dehesa', 'venta', 'casa', 24900, 'Lo Barnechea', 'Camino Los Trapenses / El Huinganal', 5, 5, 380, 950, 4, 2, true, 'disponible', array['https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&q=80&w=1200']::text[], null, 'Imponente residencia de arquitectura mediterránea contemporánea en exclusivo condominio de Los Trapenses. Gran jardín formado con piscina climatizada, quincho techado completo, sala de cine/estar y amplios espacios luminosos.', array['Piscina Climatizada', 'Quincho Gourmet Integrado', 'Jardín con Riego Automático', 'Suite de Huéspedes Independiente', 'Seguridad y Control de Acceso 24/7', 'Paneles Solares de Eficiencia Energética']::text[], 'https://my.matterport.com/show/?m=demo_luxury_2', 220000, 'Los Trapenses, Lo Barnechea, Región Metropolitana, Chile', null, null, '2026-08-18');
insert into public.properties (tenant_id, title, operation, property_type, price_uf, commune, address, bedrooms, bathrooms, built_area_m2, total_area_m2, parking_spots, storage_units, featured, status, images, video_url, description, features, virtual_tour_url, expenses_monthly_clp, map_query, lat, lng, created_at) values ((select id from public.tenants where name = 'UrbeGestión (dev)'), 'Departamento Elegante en Barrio El Golf', 'arriendo', 'departamento', 45, 'Las Condes', 'Isidora Goyenechea / Gertrudis Echeñique', 2, 2, 110, 125, 2, 1, true, 'disponible', array['https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1484154218962-a197022b5858?auto=format&fit=crop&q=80&w=1200']::text[], null, 'Magnífico departamento amoblado o semi-amoblado en el epicentro financiero y gastronómico de El Golf. Diseñado para ejecutivos y diplomáticos con conserjería premium y gimnasio.', array['Completamente Amoblado de Diseñador', 'A Pasos de Metro El Golf y Restaurantes', 'Gimnasio y Salón de Eventos', 'Estacionamiento y Bodega incluidos', 'Vigilancia con CCTV y Accesos Digitales']::text[], null, 210000, 'Isidora Goyenechea, Las Condes, Región Metropolitana, Chile', null, null, '2026-08-20');
insert into public.properties (tenant_id, title, operation, property_type, price_uf, commune, address, bedrooms, bathrooms, built_area_m2, total_area_m2, parking_spots, storage_units, featured, status, images, video_url, description, features, virtual_tour_url, expenses_monthly_clp, map_query, lat, lng, created_at) values ((select id from public.tenants where name = 'UrbeGestión (dev)'), 'Parcela Agrícola y Ganadera con Derechos de Agua Inscritos', 'venta', 'parcela_agricola', 8900, 'Melipilla (Agrícola / Parcelas)', 'Sector Culiprán / Ruta de la Fruta', 4, 3, 220, 50000, 6, 3, true, 'disponible', array['https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?auto=format&fit=crop&q=80&w=1200']::text[], null, 'Excelente campo agrícola de 50.000 m² con suelo de primera calidad para frutales (paltos, cítricos o nogales). Incluye casa patronal sólida, galpón de almacenaje, tranque acumulador y derechos de agua de riego debidamente inscritos en CBR.', array['5 Hectáreas Planas con Suelo Trumao', 'Derechos de Agua de Riego Superficiales y Subterráneos', 'Casa Patronal Estilo Colonial de 220 m²', 'Galpón de Herramientas y Maquinaria', 'Luz Trifásica y Factibilidad de Pozo Profundo', 'Camino Pavimentado hasta la Entrada']::text[], null, 0, 'Culipran, Melipilla, Región Metropolitana, Chile', null, null, '2026-08-10');
