insert into public.properties (tenant_id, title, operation, property_type, price_uf, commune, address, bedrooms, bathrooms, built_area_m2, total_area_m2, parking_spots, storage_units, featured, status, images, video_url, description, features, virtual_tour_url, expenses_monthly_clp, map_query, lat, lng, created_at) values ((select id from public.tenants where name = 'UrbeGestión (dev)'), 'Casa Familiar en Condominio con Canchas en Chicureo', 'venta', 'casa', 11900, 'Chicureo / Colina', 'Av. Chamisero / Valle Grande', 4, 3, 205, 520, 3, 1, false, 'disponible', array['https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&q=80&w=1200', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=1200']::text[], null, 'Casa de dos pisos en inmejorable ubicación de Chamisero con salida expedita a Radial Nororiente. Excelente distribución para familias con niños, condominio con seguridad extrema, plazas infantiles y canchas de pádel.', array['Condominio con Seguridad 24/7 y Cámaras Térmicas', 'Canchas de Pádel y Áreas Verdes Comunitarias', 'Gran Sala de Estar en Segundo Piso', 'Terraza Techada con Parrilla a Carbón', 'Rápida Conectividad a Vitacura en 12 Minutos']::text[], null, 115000, 'Chamisero, Colina, Región Metropolitana, Chile', null, null, '2026-08-16');
